import logging
from collections import deque


class CountingHandler(logging.Handler):
    def __init__(self, level=logging.NOTSET):
        super().__init__(level)
        self.counts = {}
        self._kept = deque(maxlen=100)

    def emit(self, record):
        self.counts[record.levelname] = self.counts.get(record.levelname, 0) + 1
        self._kept.append((record.levelno, record.getMessage()))

    def last(self, n):
        if n <= 0:
            return []
        return [text for _, text in list(self._kept)[-n:]]

    def errors(self):
        return [text for level, text in self._kept if level >= logging.ERROR]
